try:
    from tad import TAD
except ImportError:
    from pamd_eurocodes.tad import TAD

ConstructionWorks = TAD("construction works", "everything that is constructed or results from construction operations")
TypeOfBuildingOrCivilEngineeringWorks = TAD("type of building or civil engineering works", "type of construction works designating its intended purpose, e.g. dwelling house, retaining wall, industrial building, road bridge")
TypeOfConstruction = TAD("type of construction", "indication of the principal structural material, e.g. reinforced concrete construction, steel construction, timber construction, masonry construction, steel and concrete composite construction")
MethodOfConstruction = TAD("method of construction", "manner in which the execution will be carried out, e.g. cast in place, prefabricated, cantilevered")
ConstructionMaterial = TAD("construction material", "material used in construction work, e.g. concrete, steel, timber, masonry")
Structure = TAD("structure", "organised combination of connected parts designed to carry loads and provide adequate rigidity")
StructuralMember = TAD("structural member", "physically distinguishable part of a structure, e.g. a column, a beam, a slab, a foundation pile")
FormOfStructure = TAD("form of structure", "arrangement of structural members")
StructuralSystem = TAD("structural system", "load-bearing members of a building or civil engineering works and the way in which these members function together")
StructuralModel = TAD("structural model", "idealisation of the structural system used for the purposes of analysis, design and verification")
Execution = TAD("execution", "all activities carried out for the physical completion of the work including procurement, the inspection and documentation thereof")
DesignCriteria = TAD("design criteria", "quantitative formulations that describe for each limit state the conditions to be fulfilled")
DesignSituations = TAD("design situations", "sets of physical conditions representing the real conditions occurring during a certain time interval for which the design will demonstrate that relevant limit states are not exceeded")
TransientDesignSituation = TAD("transient design situation", "design situation that is relevant during a period much shorter than the design working life of the structure and which has a high probability of occurrence")
PersistentDesignSituation = TAD("persistent design situation", "design situation that is relevant during a period of the same order as the design working life of the structure")
AccidentalDesignSituation = TAD("accidental design situation", "design situation involving exceptional conditions of the structure or its exposure, including fire, explosion, impact or local failure")
FireDesign = TAD("fire design", "design of a structure to fulfil the required performance in case of fire")
SeismicDesignSituation = TAD("seismic design situation", "design situation involving exceptional conditions of the structure when subjected to a seismic event")
DesignWorkingLife = TAD("design working life", "assumed period for which a structure or part of it is to be used for its intended purpose with anticipated maintenance but without major repair being necessary")
Hazard = TAD("hazard", "for the purpose of EN 1990 to EN 1999, an unusual and severe event, e.g. an abnormal action or environmental influence, insufficient strength or resistance, or excessive deviation from intended dimensions")
LoadArrangement = TAD("load arrangement", "identification of the position, magnitude and direction of a free action")
LoadCase = TAD("load case", "compatible load arrangements, sets of deformations and imperfections considered simultaneously with fixed variable actions and permanent actions for a particular verification")
LimitStates = TAD("limit states", "states beyond which the structure no longer fulfils the relevant design criteria")
UltimateLimitStates = TAD("ultimate limit states", "states associated with collapse or with other similar forms of structural failure")
ServiceabilityLimitStates = TAD("serviceability limit states", "states that correspond to conditions beyond which specified service requirements for a structure or structural member are no longer met")
IrreversibleServiceabilityLimitStates = TAD("irreversible serviceability limit states", "serviceability limit states where some consequences of actions exceeding the specified service requirements will remain when the actions are removed")
ReversibleServiceabilityLimitStates = TAD("reversible serviceability limit states", "serviceability limit states where no consequences of actions exceeding the specified service requirements will remain when the actions are removed")
ServiceabilityCriterion = TAD("serviceability criterion", "design criterion for a serviceability limit state")
Resistance = TAD("resistance", "capacity of a member or component, or a cross-section of a member or component of a structure, to withstand actions without mechanical failure e.g. bending resistance, buckling resistance, tension resistance")
Strength = TAD("strength", "mechanical property of a material indicating its ability to resist actions, usually given in units of stress")
Reliability = TAD("reliability", "ability of a structure or a structural member to fulfil the specified requirements, including the design working life, for which it has been designed. Reliability is usually expressed in probabilistic terms")
ReliabilityDifferentiation = TAD("reliability differentiation", "measures intended for the socio-economic optimisation of the resources to be used to build construction works, taking into account all the expected consequences of failures and the cost of the construction works")
BasicVariable = TAD("basic variable", "part of a specified set of variables representing physical quantities which characterise actions and environmental influences, geometrical quantities, and material properties including soil properties")
Maintenance = TAD("maintenance", "set of activities performed during the working life of the structure in order to enable it to fulfil the requirements for reliability")
Repair = TAD("repair", "activities performed to preserve or to restore the function of a structure that fall outside the definition of maintenance")
NominalValue = TAD("nominal value", "value fixed on non-statistical bases, for instance on acquired experience or on physical conditions")
Action = TAD("action (F)", "a) Set of forces (loads) applied to the structure (direct action); b) Set of imposed deformations or accelerations caused for example, by temperature changes, moisture variation, uneven settlement or earthquakes (indirect action).")
EffectOfAction = TAD("effect of action (E)", "effect of actions (or action effect) on structural members, (e.g. internal force, moment, stress, strain) or on the whole structure (e.g. deflection, rotation)")
PermanentAction = TAD("permanent action (G)", "action that is likely to act throughout a given reference period and for which the variation in magnitude with time is negligible, or for which the variation is always in the same direction (monotonic) until the action attains a certain limit value")
VariableAction = TAD("variable action (Q)", "action for which the variation in magnitude with time is neither negligible nor monotonic")
AccidentalAction = TAD("accidental action (A)", "action, usually of short duration but of significant magnitude, that is unlikely to occur on a given structure during the design working life")
SeismicAction = TAD("seismic action (AE)", "action that arises due to earthquake ground motions")
GeotechnicalAction = TAD("geotechnical action", "action transmitted to the structure by the ground, fill or groundwater")
FixedAction = TAD("fixed action", "action that has a fixed distribution and position over the structure or structural member such that the magnitude and direction of the action are determined unambiguously for the whole structure or structural member if this magnitude and direction are determined at one point on the structure or structural member")
FreeAction = TAD("free action", "action that may have various spatial distributions over the structure")
SingleAction = TAD("single action", "action that can be assumed to be statistically independent in time and space of any other action acting on the structure")
StaticAction = TAD("static action", "action that does not cause significant acceleration of the structure or structural members")
DynamicAction = TAD("dynamic action", "action that causes significant acceleration of the structure or structural members")
QuasiStaticAction = TAD("quasi-static action", "dynamic action represented by an equivalent static action in a static model")
CharacteristicValueOfAnAction = TAD("characteristic value of an action (Fk)", "principal representative value of an action")
ReferencePeriod = TAD("reference period", "chosen period of time that is used as a basis for assessing statistically variable actions, and possibly for accidental actions")
CombinationValueOfAVariableAction = TAD("combination value of a variable action (ψ_0 Q_k)", "value chosen - in so far as it can be fixed on statistical bases - so that the probability that the effects caused by the combination will be exceeded is approximately the same as by the characteristic value of an individual action. It may be expressed as a determined part of the characteristic value by using a factor ψ_0 ≤ 1")
FrequentValueOfAVariableAction = TAD("frequent value of a variable action (ψ_1 Q_k)", "value determined - in so far as it can be fixed on statistical bases - so that either the total time, within the reference period, during which it is exceeded is only a small given part of the reference period, or the frequency of it being exceeded is limited to a given value. It may be expressed as a determined part of the characteristic value by using a factor ψ_1 ≤ 1")
QuasiPermanentValueOfAVariableAction = TAD("quasi-permanent value of a variable action (ψ_2 Q_k)", "value determined so that the total period of time for which it will be exceeded is a large fraction of the reference period. It may be expressed as a determined part of the characteristic value by using a factor ψ_2 ≤ 1")
AccompanyingValueOfAVariableAction = TAD("accompanying value of a variable action (ψ Q_k)", "value of a variable action that accompanies the leading action in a combination")
RepresentativeValueOfAnAction = TAD("representative value of an action (Frep)", "value used for the verification of a limit state. A representative value may be the characteristic value (Fk) or an accompanying value (ψFk)")
DesignValueOfAnAction = TAD("design value of an action (Fd)", "value obtained by multiplying the representative value by the partial factor γ_f")
CombinationOfActions = TAD("combination of actions", "set of design values used for the verification of the structural reliability for a limit state under the simultaneous influence of different actions")
CharacteristicValue = TAD("characteristic value (Xk or Rk)", "value of a material or product property having a prescribed probability of not being attained in a hypothetical unlimited test series. This value generally corresponds to a specified fractile of the assumed statistical distribution of the particular property of the material or product. A nominal value is used as the characteristic value in some circumstances")
DesignValueOfAMaterialOrProductProperty = TAD("design value of a material or product property (Xd or Rd)", "value obtained by dividing the characteristic value by a partial factor γ_m or γ_M, or, in special circumstances, by direct determination")
NominalValueOfAMaterialOrProductProperty = TAD("nominal value of a material or product property (Xnom or Rnom)", "value normally used as a characteristic value and established from an appropriate document such as a European Standard or Prestandard")
CharacteristicValueOfAGeometricalProperty = TAD("characteristic value of a geometrical property (ak)", "value usually corresponding to the dimensions specified in the design. Where relevant, values of geometrical quantities may correspond to some prescribed fractiles of the statistical distribution")
DesignValueOfAGeometricalProperty = TAD("design value of a geometrical property (ad)", "generally a nominal value. Where relevant, values of geometrical quantities may correspond to some prescribed fractile of the statistical distribution")
StructuralAnalysis = TAD("structural analysis", "procedure or algorithm for determination of action effects in every point of a structure")
GlobalAnalysis = TAD("global analysis", "determination, in a structure, of a consistent set of either internal forces and moments, or stresses, that are in equilibrium with a particular defined set of actions on the structure, and depend on geometrical, structural and material properties")
FirstOrderLinearElasticAnalysisWithoutRedistribution = TAD("first order linear-elastic analysis without redistribution", "elastic structural analysis based on linear stress/strain or moment/curvature laws and performed on the initial geometry")
FirstOrderLinearElasticAnalysisWithRedistribution = TAD("first order linear-elastic analysis with redistribution", "linear elastic analysis in which the internal moments and forces are modified for structural design, consistently with the given external actions and without more explicit calculation of the rotation capacity")
SecondOrderLinearElasticAnalysis = TAD("second order linear-elastic analysis", "elastic structural analysis, using linear stress/strain laws, applied to the geometry of the deformed structure")
FirstOrderNonLinearAnalysis = TAD("first order non-linear analysis", "structural analysis, performed on the initial geometry, that takes account of the non-linear deformation properties of materials")
SecondOrderNonLinearAnalysis = TAD("second order non-linear analysis", "structural analysis, performed on the geometry of the deformed structure, that takes account of the non-linear deformation properties of materials")
FirstOrderElasticPerfectlyPlasticAnalysis = TAD("first order elastic-perfectly plastic analysis", "structural analysis based on moment/curvature relationships consisting of a linear elastic part followed by a plastic part without hardening, performed on the initial geometry of the structure")
SecondOrderElasticPerfectlyPlasticAnalysis = TAD("second order elastic-perfectly plastic analysis", "structural analysis based on moment/curvature relationships consisting of a linear elastic part followed by a plastic part without hardening, performed on the geometry of the displaced (or deformed) structure")
ElastoPlasticAnalysis = TAD("elasto-plastic analysis (first or second order)", "structural analysis that uses stress-strain or moment/curvature relationships consisting of a linear elastic part followed by a plastic part with or without hardening")
RigidPlasticAnalysis = TAD("rigid plastic analysis", "analysis, performed on the initial geometry of the structure, that uses limit analysis theorems for direct assessment of the ultimate loading")